            'uses: IstiN/dmtools-agentic-workflows/.github/workflows/factory-teammate.yml@'),
        reason: 'the factory home moved to dmtools-agentic-workflows '
            '(engine pin stays dmtools-agents via factory_ref)',
      );
      expect(
        yaml,
