import json,sys
d=json.load(sys.stdin)
runs=d.get('checkRuns',d.get('data',d))
if isinstance(runs,dict): runs=runs.get('checkRuns',[])
for r in runs:
    print(r.get('name'), '|', r.get('status'), '|', r.get('conclusion'))
